stepxmp.pre:
fn::footnote-call {
    content: counter(footnote, symbols("*" "†" "‡"));
}

fn::footnote-marker {
    content: counter(footnote, symbols("*" "†" "‡")) " ";
}

::footnote-call {
    font-size: 70%;
    vertical-align: super;
    line-height: 0;
}

::footnote-marker {
    font-weight: bold;
}

fn::footnote-call {
    content: "[" counter(footnote) "]";
}

fn::footnote-marker {
    content: "[" counter(footnote) "] ";
}

fn[callout] {
    counter-increment: footnote -1;
}

fn[callout]::footnote-call {
    content: attr(callout);
}

fn[callout]::footnote-marker {
    content: attr(callout) " ";
}

fn {
    float: footnote;
    footnote-display: compact;
    margin-inline-end: 1em;
}
